const icon=(name,extra='')=>`<svg class="icon ${extra}" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.grid}"/></svg>`;
const currency=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const date=v=>v?new Date(v.slice(0,10)+'T12:00:00').toLocaleDateString('pt-BR'):'—';
const initials=v=>String(v).split(' ').filter(Boolean).slice(0,2).map(s=>s[0]).join('');
const avatar=name=>`<span class="avatar">${esc(initials(name))}</span>`;
const person=(name,email='')=>`<div class="person">${avatar(name)}<div><strong>${esc(name)}</strong><small>${esc(email)}</small></div></div>`;
const badge=(s)=>`<span class="badge ${['Vencido','Inativo'].includes(s)?'danger':['Pendente'].includes(s)?'warn':['Cancelado'].includes(s)?'neutral':''}">${esc(s)}</span>`;
const btn=(label,action,ico='',type='',id='')=>`<button class="button ${type}" data-action="${action}" ${id!==''?`data-id="${id}"`:''}>${ico?icon(ico):''}${label}</button>`;
const ibtn=(label,action,ico,id='')=>`<button class="icon-button" aria-label="${esc(label)}" title="${esc(label)}" data-action="${action}" data-id="${id}">${icon(ico)}</button>`;
const empty=(title='Nada por aqui ainda',description='Os registros aparecerão aqui assim que forem cadastrados.')=>`<div class="empty">${icon('clipboard')}<h3>${esc(title)}</h3><p>${esc(description)}</p></div>`;
let demoEnabled=false;
let state=null,route='dashboard',detailTab='overview',tablePage=1,query='',filter='',sort='default',period=6,collapsed=false,tableConfig=null,lastFocus=null,exerciseDraft=[],runWorkout=null,draftKey='';
let toastTimer;
let restInterval=null, restDeadline=0, restRemaining=0;
function stopRestTimer(){clearInterval(restInterval);restInterval=null}
function renderRestTimer(){const output=$('#rest-time');if(!output)return;const seconds=restDeadline?Math.max(0,Math.ceil((restDeadline-Date.now())/1000)):restRemaining;output.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if(restDeadline&&seconds===0){stopRestTimer();restDeadline=0;restRemaining=0;$('#rest-status').textContent='Descanso concluído. Pronto para a próxima série.';$('#rest-pause').disabled=true;toast('Descanso concluído. Próxima série!')}}
function startRestTimer(seconds,name){stopRestTimer();restRemaining=Number(seconds);restDeadline=Date.now()+restRemaining*1000;$('#rest-panel').hidden=false;$('#rest-status').textContent=`Descanso · ${name}`;$('#rest-pause').disabled=false;$('#rest-pause').textContent='Pausar';renderRestTimer();restInterval=setInterval(renderRestTimer,250)}
function toggleRestTimer(){if(restDeadline){restRemaining=Math.max(0,Math.ceil((restDeadline-Date.now())/1000));restDeadline=0;stopRestTimer();$('#rest-pause').textContent='Continuar'}else if(restRemaining>0){restDeadline=Date.now()+restRemaining*1000;restInterval=setInterval(renderRestTimer,250);$('#rest-pause').textContent='Pausar'}renderRestTimer()}

function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',4500)}
async function api(path,method='GET',body){const res=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json',...(state?.csrf?{'X-CSRF-Token':state.csrf}:{})},...(body?{body:JSON.stringify(body)}:{})});const data=await res.json();if(!res.ok){if(res.status===401&&path!=='login'){state=null;renderLogin()}throw Error(data.error||'Não foi possível concluir.')}return data}
async function refresh(){state=await api('state')}
function roleName(){return {admin:'Administrador',teacher:'Professor',student:'Aluno'}[state.user.role]}
function studentName(id){return state.students.find(s=>s.id===id)?.name||'Aluno'}
function navigate(to){route=to;query='';filter='';sort='default';tablePage=1;detailTab='overview';history.replaceState(null,'','#'+to);render();window.scrollTo(0,0)}
function allowedRoutes(){return state.user.role==='admin'?['dashboard','students','teachers','exercises','workouts','assessments','attendance','plans','payments','reports','settings']:state.user.role==='teacher'?['dashboard','students','exercises','workouts','assessments','attendance']:['dashboard','workouts','history','assessments','attendance','payments','exercises']}
const labels={dashboard:'Visão geral',students:'Alunos',teachers:'Professores',exercises:'Exercícios',workouts:'Treinos',assessments:'Avaliações físicas',attendance:'Frequência',plans:'Planos',payments:'Financeiro',reports:'Relatórios',settings:'Configurações',profile:'Meu perfil',history:'Histórico de treinos'};
const navIcons={dashboard:'grid',students:'users',teachers:'teacher',exercises:'dumbbell',workouts:'clipboard',assessments:'chart',attendance:'calendar',plans:'card',payments:'wallet',reports:'chart',settings:'settings',profile:'users',history:'clock'};
function navItem(k){return `<button class="nav-item ${route.split('/')[0]===k?'active':''}" data-route="${k}" title="${labels[k]}">${icon(navIcons[k])}<span>${state.user.role==='teacher'&&k==='students'?'Meus alunos':labels[k]}</span>${k==='students'?`<span class="nav-count">${state.students.length}</span>`:''}</button>`}
function render(){if(!state)return renderLogin();let base=route.split('/')[0];if(!allowedRoutes().includes(base)&&base!=='profile'){route='dashboard';base='dashboard'}const groups=[['PRINCIPAL',['dashboard']],['GESTÃO ESPORTIVA',['students','teachers','workouts','exercises','assessments','attendance','history']],['GESTÃO FINANCEIRA',['plans','payments','reports']]];$('#app').innerHTML=`<div class="shell ${collapsed?'collapsed':''}"><aside class="sidebar"><a href="#dashboard" class="brand" data-route="dashboard"><span class="brand-symbol">${icon('dumbbell')}</span><span class="brand-text">gym<em>flow</em><span class="violet">.</span></span></a><div class="workspace"><span class="workspace-logo">GF</span><span>${esc(state.settings.gym_name)}<small class="dim" style="display:block;font-size:9px">Seu espaço de gestão</small></span>${icon('down')}</div><nav>${groups.map(([name,keys])=>{const selected=keys.filter(k=>allowedRoutes().includes(k));return selected.length?`<div class="nav-group"><span class="label">${name}</span>${selected.map(navItem).join('')}</div>`:''}).join('')}</nav><div class="side-bottom"><div class="help-card"><div class="row">${icon('spark')}<strong style="font-size:11px">Gestão em movimento.</strong></div><p>Mais tempo para o que importa: seus alunos.</p>${btn('Conheça seu espaço','help','arrow','small')}</div>${state.user.role==='admin'?navItem('settings'):''}<div class="side-user"><button class="icon-button" data-route="profile" aria-label="Meu perfil">${avatar(state.user.name)}</button><div class="user-info"><strong>${esc(state.user.name.split(' ')[0])}</strong><small>${roleName()}</small></div><span style="margin-left:auto">${ibtn('Recolher menu','collapse','collapse')}</span></div></div></aside><main class="main"><header class="topbar"><div class="row">${ibtn('Abrir menu','mobile-menu','menu')}<div class="breadcrumb">Workspace <span>/</span><span>${labels[base]||'Perfil do aluno'}</span></div></div><div class="top-actions"><form class="top-search" id="global-search">${icon('search')}<input aria-label="Buscar exercícios" placeholder="Buscar na biblioteca…"><span class="key">↵</span></form><span class="notification-button">${ibtn('Notificações','notifications','bell')}</span><span style="width:1px;height:22px;background:var(--line)"></span>${ibtn('Sair da conta','logout','logout')}</div></header><div class="content" id="content"></div></main><nav class="mobile-nav" aria-label="Navegação principal">${(state.user.role==='student'?['dashboard','workouts','assessments','profile']:['dashboard','students','attendance','profile']).map(k=>`<button data-route="${k}" class="${base===k?'active':''}">${icon(navIcons[k])}${k==='dashboard'?'Início':labels[k]}</button>`).join('')}</nav></div>`;
const mobileBtn=$('[data-action="mobile-menu"]');mobileBtn?.classList.add('mobile-toggle');
const pages={dashboard,students,teachers,exercises,workouts,assessments,attendance,plans,payments,reports,settings,profile,history:workoutHistory};(pages[base]||dashboard)();
$('#content').insertAdjacentHTML('beforeend',`<footer class="bottom-note"><span>© ${new Date().getFullYear()} GymFlow · Gestão em movimento</span><span><span class="status-dot"></span>${state.demo?'Ambiente de demonstração · dados fictícios':'Conexão ativa'} </span></footer>`);
$('#global-search')?.addEventListener('submit',e=>{e.preventDefault();const value=e.currentTarget.querySelector('input').value;navigate('exercises');query=value;$('#table-search').value=value;updateTable()})}
function heading(title,subtitle,action=''){return `<div class="between page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`}
function panel(title,sub,body,action=''){return `<section class="panel"><header class="panel-header"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</header><div class="panel-body">${body}</div></section>`}
function stat(title,value,ico,foot,trend=''){return `<article class="stat"><div class="stat-head"><span>${title}</span><span class="stat-icon">${icon(ico)}</span></div><div class="stat-value number">${value}</div><div class="stat-foot">${trend?`<span class="trend">${trend}</span>`:''}<small>${foot}</small></div></article>`}
function sums(){const month=state.today.slice(0,7);return {active:state.students.filter(s=>s.active).length,revenue:state.payments.filter(p=>p.status==='Pago'&&p.paid_at?.startsWith(month)).reduce((s,p)=>s+p.amount,0),pending:state.payments.filter(p=>['Pendente','Vencido'].includes(p.status)),today:state.attendance.filter(a=>a.day===state.today).length}}
function series(kind='revenue',count=6){let values=[];for(let i=count-1;i>=0;i--){const date=new Date(state.today+'T12:00:00');date.setDate(1);date.setMonth(date.getMonth()-i);const key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;values.push({label:date.toLocaleString('pt-BR',{month:'short'}).replace('.',''),value:kind==='revenue'?state.payments.filter(p=>p.status==='Pago'&&p.paid_at?.startsWith(key)).reduce((s,p)=>s+p.amount,0):state.students.filter(s=>s.enrollment.startsWith(key)).length})}return values}
function lineChart(data,money=false){if(!data.length)return empty('Sem registros no período');const max=Math.max(...data.map(d=>d.value),1)*1.2,w=600,h=190,left=45,right=15,top=14,bottom=29;const iw=w-left-right,ih=h-top-bottom;const coords=data.map((d,i)=>[left+i*iw/Math.max(1,data.length-1),top+ih-(d.value/max)*ih]);const points=coords.map(p=>p.join(',')).join(' ');const area=`${left},${top+ih} ${points} ${coords.at(-1)[0]},${top+ih}`;return `<div class="chart"><svg role="img" aria-label="${money?'Receita por mês':'Evolução por período'}" viewBox="0 0 ${w} ${h}"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#9c88ff" stop-opacity=".18"/><stop offset="1" stop-color="#9c88ff" stop-opacity="0"/></linearGradient></defs>${[0,.25,.5,.75,1].map(v=>`<line x1="${left}" x2="${w-right}" y1="${top+ih*v}" y2="${top+ih*v}" stroke="#2a2935" stroke-dasharray="3 5"/><text x="${left-9}" y="${top+ih*v+3}" text-anchor="end">${money?Math.round(max*(1-v)/1000)+'k':Math.round(max*(1-v))}</text>`).join('')}<polygon points="${area}" fill="url(#fill)"/><polyline points="${points}" stroke="#9c88ff" stroke-width="2.3" fill="none" stroke-linejoin="round"/>${coords.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="#191923" stroke="#b2a0ff" stroke-width="2"><title>${esc(data[i].label)}: ${money?currency(data[i].value):data[i].value}</title></circle><text x="${x}" y="${h-5}" text-anchor="middle">${esc(data[i].label)}</text>`).join('')}</svg></div>`}
function frequencyChart(){const values=[];for(let i=6;i>=0;i--){const d=new Date(state.today+'T12:00:00');d.setDate(d.getDate()-i);const key=d.toLocaleDateString('en-CA');const iso=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');values.push({label:d.toLocaleDateString('pt-BR',{weekday:'short'}).slice(0,3),value:state.attendance.filter(a=>a.day===iso).length})}const max=Math.max(1,...values.map(d=>d.value));return `<div class="occupancy">${values.map((d,i)=>`<div class="bar-group"><div class="bar ${i===6?'current':''}" style="height:${Math.max(2,d.value/max*125)}px" title="${d.label}: ${d.value} check-ins"></div><small>${d.label}</small></div>`).join('')}</div><div class="frequency-foot"><span>Total nos últimos 7 dias</span><strong>${values.reduce((s,d)=>s+d.value,0)} check-ins</strong></div>`}
function revenuePanel(){const data=series('revenue',period);return `<section class="panel"><header class="panel-header"><div><h2>Visão financeira</h2><p>Acompanhe a receita da sua academia</p></div><div class="chart-controls">${[3,6,12].map(n=>`<button data-action="period" data-id="${n}" class="${period===n?'active':''}">${n} meses</button>`).join('')}</div></header><div class="between" style="padding-right:22px"><div class="chart-summary"><strong>${currency(data.reduce((s,d)=>s+d.value,0))}</strong><span>no período</span></div><span class="legend">Receita</span></div>${lineChart(data,true)}</section>`}
function dashboard(){if(state.user.role==='student')return studentDashboard();if(state.user.role==='teacher')return teacherDashboard();const s=sums(),pending=s.pending,expired=pending.filter(p=>p.status==='Vencido');$('#content').innerHTML=heading('Sua academia, em movimento.',`Olá, ${esc(state.user.name.split(' ')[0])}. Aqui está o resumo da sua operação.`,`<div class="row"><span class="date-select">${icon('calendar')}${new Date(state.today+'T12:00:00').toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'})}</span>${btn('Novo aluno','new-student','plus','primary')}</div>`)+`<div class="stats">${stat('Alunos ativos',s.active,'users',`${state.students.length} alunos cadastrados`)}${stat('Receita do mês',currency(s.revenue),'wallet','Pagamentos registrados neste mês')}${stat('Mensalidades pendentes',currency(pending.reduce((a,p)=>a+p.amount,0)),'card',`${pending.length} cobranças a receber`,expired.length+' vencidas')}${stat('Check-ins hoje',s.today,'calendar','Presenças registradas no dia')}</div><div class="dashboard-grid">${revenuePanel()}${panel('Frequência da semana','Um olhar sobre a rotina dos seus alunos',frequencyChart(),'<span class="legend">Check-ins</span>')}</div><div class="dashboard-grid"><section class="panel"><header class="panel-header"><div><h2>Alunos recentes</h2><p>Quem está construindo uma nova rotina</p></div><button class="text-link" data-route="students">Ver todos ${icon('arrow')}</button></header><div style="height:15px"></div><div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Plano</th><th>Status</th><th></th></tr></thead><tbody>${[...state.students].sort((a,b)=>b.enrollment.localeCompare(a.enrollment)).slice(0,5).map(s=>`<tr><td>${person(s.name,s.email)}</td><td>${esc(s.plan||'Sem plano')}</td><td>${badge(s.active?'Ativo':'Inativo')}</td><td>${ibtn('Abrir perfil','student-detail','chevron',s.id)}</td></tr>`).join('')}</tbody></table></div></section>${panel('Precisa da sua atenção','Pequenas ações, grandes resultados',`<div class="alert-item"><span class="alert-icon">${icon('wallet')}</span><div><strong>${expired.length} mensalidades vencidas</strong><p>${currency(expired.reduce((a,p)=>a+p.amount,0))} aguardando regularização.</p><button class="text-link" data-route="payments">Acessar financeiro ${icon('arrow')}</button></div></div><div class="alert-item"><span class="alert-icon purple">${icon('clipboard')}</span><div><strong>${state.students.filter(s=>s.active&&!state.workouts.some(w=>w.student_id===s.id&&w.active)).length} alunos sem treino ativo</strong><p>Conecte cada aluno ao próximo passo.</p><button class="text-link" data-route="workouts">Gerenciar treinos ${icon('arrow')}</button></div></div><div class="quick-actions">${btn('Novo check-in','new-attendance','calendar')}${btn('Registrar pagamento','go-payments','wallet')}${btn('Criar treino','new-workout','dumbbell')}${btn('Ver relatórios','go-reports','chart')}</div>`)}</div>`}
function teacherDashboard(){const pending=state.students.filter(s=>!state.assessments.some(a=>a.student_id===s.id&&a.next_date>=state.today));$('#content').innerHTML=heading(`Vamos evoluir juntos, ${esc(state.user.name.split(' ')[0])}.`,'Seu acompanhamento faz a diferença em cada treino.',btn('Criar ficha de treino','new-workout','plus','primary'))+`<div class="stats">${stat('Meus alunos',state.students.length,'users','Alunos sob sua responsabilidade')}${stat('Treinos ativos',state.workouts.filter(w=>w.active).length,'dumbbell','Fichas disponíveis para os alunos')}${stat('Avaliações pendentes',pending.length,'clipboard','Sem reavaliação futura registrada')}${stat('Check-ins hoje',sums().today,'calendar','Presenças dos seus alunos')}</div><div class="dashboard-grid">${panel('Seu acompanhamento','Próximas ações por aluno',state.students.slice(0,6).map(s=>`<div class="between activity-item">${person(s.name,s.objective)}${btn('Ver perfil','student-detail','chevron','small',s.id)}</div>`).join('')||empty())}${panel('Frequência dos seus alunos','Últimos 7 dias',frequencyChart())}</div>`+panel('Ações do dia','Continue de onde você parou',`<div class="row" style="flex-wrap:wrap">${btn('Registrar avaliação','new-assessment','chart')}${btn('Biblioteca de exercícios','go-exercises','dumbbell')}${btn('Registrar check-in','new-attendance','calendar')}</div>`)}
function studentDashboard(){const s=state.students[0],w=state.workouts.find(w=>w.active),visits=state.attendance.filter(a=>a.day.startsWith(state.today.slice(0,7))).length,pending=state.payments.filter(p=>['Vencido','Pendente'].includes(p.status)),assessment=state.assessments[0];$('#content').innerHTML=heading(`Seu próximo passo começa aqui, ${esc(state.user.name.split(' ')[0])}.`,'Consistência hoje. Evolução no seu ritmo.',btn('Fazer check-in','self-checkin','calendar','primary'))+`<div class="stats">${stat('Visitas neste mês',visits,'calendar','Cada presença conta')}${stat('Treinos concluídos',state.sessions.length,'dumbbell','Sua jornada registrada')}${stat('Meu plano',esc(s?.plan||'Sem plano'),'card',pending.length?`${pending.length} cobranças a consultar`:'Nenhuma cobrança em aberto')}${stat('Próxima avaliação',assessment?date(assessment.next_date):'—','chart','Acompanhamento com seu professor')}</div><section class="workout-hero"><span class="label violet">SEU TREINO · PRÓXIMO PASSO</span><h2>${esc(w?.name||'Vamos preparar sua rotina')}</h2><p>${w?`Ficha ${esc(w.division)} · ${w.exercises.length} exercícios · ${esc(w.objective)}`:'Seu professor ainda não disponibilizou um treino.'}</p>${w?btn('Iniciar treino','start-workout','play','primary',w.id):btn('Conhecer meu perfil','go-profile','users')}</section><div class="dashboard-grid">${panel('Sua semana em movimento','Suas presenças nos últimos 7 dias',frequencyChart())}${panel('Últimas atividades','Seu esforço tem história',state.sessions.slice(0,4).map(s=>`<div class="activity-item"><div class="workout-letter">${icon('check')}</div><div><strong>Treino concluído</strong><p class="muted">${date(s.created)} · ${s.logs.length} exercícios registrados</p></div></div>`).join('')||empty('Sua história começa no primeiro treino','Ao concluir um treino, ele aparecerá aqui.'))}</div>`}
function tableView(title,subtitle,config,action=''){tableConfig=config;$('#content').innerHTML=heading(title,subtitle,action)+`<section class="panel"><div class="table-toolbar"><div class="search-field">${icon('search')}<input id="table-search" aria-label="Buscar ${esc(title)}" placeholder="${esc(config.placeholder||'Buscar por nome…')}" value="${esc(query)}"></div>${config.filters?`<select id="table-filter" aria-label="Filtrar registros"><option value="">Todos os ${esc(config.filterName||'status')}</option>${config.filters.map(v=>`<option ${filter===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:''}<select id="table-sort" aria-label="Ordenar registros"><option value="default">Mais recentes</option><option value="asc" ${sort==='asc'?'selected':''}>A → Z</option><option value="desc" ${sort==='desc'?'selected':''}>Z → A</option></select>${config.export?btn('Exportar CSV','export','download','ghost small'):''}</div><div id="table-result"></div></section>`;updateTable();$('#table-search').addEventListener('input',e=>{query=e.target.value;tablePage=1;updateTable()});$('#table-filter')?.addEventListener('change',e=>{filter=e.target.value;tablePage=1;updateTable()});$('#table-sort').addEventListener('change',e=>{sort=e.target.value;tablePage=1;updateTable()})}
function filteredRows(){const c=tableConfig;let data=c.rows.filter(r=>(c.search(r).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')))&&(!filter||c.filter(r)===filter));if(sort!=='default')data.sort((a,b)=>c.search(a).localeCompare(c.search(b),'pt-BR')*(sort==='asc'?1:-1));return data}
function updateTable(){const c=tableConfig,all=filteredRows(),size=7,pages=Math.max(1,Math.ceil(all.length/size));tablePage=Math.min(tablePage,pages);const data=all.slice((tablePage-1)*size,tablePage*size);$('#table-result').innerHTML=(data.length?`<div class="table-wrap"><table><thead><tr>${c.headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${data.map(c.render).join('')}</tbody></table></div>`:empty('Nenhum registro encontrado','Tente outra busca ou cadastre o primeiro registro.'))+`<div class="table-foot"><span>${all.length?`${(tablePage-1)*size+1}–${Math.min(tablePage*size,all.length)} de ${all.length}`:'0'} registros</span><div class="pagination">${btn('←','prev-page','','ghost small')}<span style="padding:0 9px">${tablePage} / ${pages}</span>${btn('→','next-page','','ghost small')}</div></div>`}
function students(){if(route.includes('/'))return studentDetail(Number(route.split('/')[1]));tableView(state.user.role==='teacher'?'Meus alunos':'Alunos','Cada pessoa, uma jornada. Gerencie tudo em um só lugar.',{headers:['Aluno','Plano','Professor','Matrícula','Status','Ações'],rows:[...state.students].reverse(),search:r=>r.name+' '+r.email,filters:['Ativo','Inativo'],filter:r=>r.active?'Ativo':'Inativo',export:true,render:s=>`<tr><td>${person(s.name,s.email)}</td><td>${esc(s.plan||'Sem plano')}</td><td>${esc(s.teacher||'Não atribuído')}</td><td>${date(s.enrollment)}</td><td>${badge(s.active?'Ativo':'Inativo')}</td><td>${ibtn('Ver perfil','student-detail','eye',s.id)}${state.user.role==='admin'?ibtn('Editar aluno','edit-student','edit',s.id):''}</td></tr>`},state.user.role==='admin'?btn('Novo aluno','new-student','plus','primary'):'')}
function teachers(){tableView('Professores','Profissionais que transformam movimento em evolução.',{headers:['Professor','Especialidade','Registro','Alunos','Status','Ações'],rows:[...state.teachers].reverse(),search:r=>r.name+' '+r.email,filters:['Ativo','Inativo'],filter:r=>r.active?'Ativo':'Inativo',render:t=>`<tr><td>${person(t.name,t.email)}</td><td>${esc(t.specialty)}</td><td>${esc(t.registration||'—')}</td><td>${state.students.filter(s=>s.teacher_id===t.id).length}</td><td>${badge(t.active?'Ativo':'Inativo')}</td><td>${ibtn('Editar professor','edit-teacher','edit',t.id)}${t.active?ibtn('Desativar professor','deactivate-teacher','trash',t.id):''}</td></tr>`},btn('Novo professor','new-teacher','plus','primary'))}
function exercises(){tableView('Biblioteca de exercícios','Uma base para orientar cada movimento.',{headers:['Exercício','Grupo muscular','Equipamento','Nível','Status','Ações'],rows:state.exercises,search:r=>r.name+' '+r.equipment+' '+r.level,placeholder:'Buscar nome, equipamento ou nível…',filters:[...new Set(state.exercises.map(e=>e.muscle))],filterName:'grupos',filter:r=>r.muscle,render:e=>`<tr><td><div class="row"><span class="stat-icon">${icon('dumbbell')}</span><strong style="color:var(--text);font-weight:500">${esc(e.name)}</strong></div></td><td>${esc(e.muscle)}</td><td>${esc(e.equipment)}</td><td>${esc(e.level)}</td><td>${badge(e.active?'Ativo':'Inativo')}</td><td>${ibtn('Instruções','view-exercise','eye',e.id)}${state.user.role!=='student'?ibtn('Editar exercício','edit-exercise','edit',e.id):''}</td></tr>`},state.user.role!=='student'?btn('Novo exercício','new-exercise','plus','primary'):'')}
function workouts(){tableView(state.user.role==='student'?'Meus treinos':'Treinos','Fichas personalizadas para uma evolução consistente.',{headers:['Treino','Aluno','Divisão','Exercícios','Atualização','Status','Ações'],rows:state.workouts,search:r=>r.name+' '+studentName(r.student_id),filters:['Ativo','Inativo'],filter:r=>r.active?'Ativo':'Inativo',render:w=>`<tr><td><strong style="color:var(--text);font-weight:500">${esc(w.name)}</strong></td><td>${esc(studentName(w.student_id))}</td><td><span class="badge">Ficha ${esc(w.division)}</span></td><td>${w.exercises.length}</td><td>${date(w.updated)}</td><td>${badge(w.active?'Ativo':'Inativo')}</td><td>${ibtn('Abrir ficha','view-workout','eye',w.id)}${state.user.role==='student'?(w.active?ibtn('Iniciar treino','start-workout','play',w.id):''):ibtn('Editar ficha','edit-workout','edit',w.id)}</td></tr>`},state.user.role!=='student'?btn('Criar ficha','new-workout','plus','primary'):'')}
function assessments(){tableView(state.user.role==='student'?'Minha evolução':'Avaliações físicas','Acompanhamento individual, com respeito à sua jornada.',{headers:['Aluno','Data','Peso','Altura','Reavaliação','Ações'],rows:state.assessments,search:r=>studentName(r.student_id)+' '+r.date,render:a=>`<tr><td>${person(studentName(a.student_id))}</td><td>${date(a.date)}</td><td>${a.weight} kg</td><td>${a.height} cm</td><td>${date(a.next_date)}</td><td>${ibtn('Ver avaliação e evolução','view-assessment','chart',a.id)}${state.user.role!=='student'?ibtn('Editar avaliação','edit-assessment','edit',a.id):''}</td></tr>`},state.user.role!=='student'?btn('Nova avaliação','new-assessment','plus','primary'):'')}
function attendance(){tableView('Frequência','Cada check-in é um compromisso com a evolução.',{headers:['Aluno','Data','Horário','Registro'],rows:state.attendance,search:r=>studentName(r.student_id)+' '+date(r.day),filters:['Hoje','Este mês'],filterName:'períodos',filter:r=>filter==='Hoje'?(r.day===state.today?'Hoje':''):r.day.startsWith(state.today.slice(0,7))?'Este mês':'',export:true,render:a=>`<tr><td>${person(studentName(a.student_id))}</td><td>${date(a.day)}</td><td>${esc(a.time)}</td><td>${badge('Confirmado')}</td></tr>`},btn('Fazer check-in',state.user.role==='student'?'self-checkin':'new-attendance','plus','primary'))}
function plans(){$('#content').innerHTML=heading('Planos da academia','Experiências que acompanham diferentes objetivos.',btn('Novo plano','new-plan','plus','primary'))+`<div class="card-grid">${state.plans.map(p=>`<article class="entity-card"><div class="between"><span class="stat-icon">${icon('card')}</span>${badge(p.active?'Ativo':'Inativo')}</div><div><h2 style="font-size:21px">${esc(p.name)}</h2><p style="margin-top:6px">${esc(p.description)}</p></div><div class="price">${currency(p.price)} <small>/ ${p.months===1?'mês':p.months+' meses'}</small></div><ul>${p.benefits.split('•').map(b=>`<li>${esc(b.trim())}</li>`).join('')}</ul><p>${state.subscriptions.filter(s=>s.plan_id===p.id&&s.active).length} assinaturas ativas</p><footer>${btn('Editar plano','edit-plan','edit','small',p.id)}${p.active?btn('Desativar','deactivate-plan','','ghost small',p.id):''}</footer></article>`).join('')}</div>`}
function payments(){const admin=state.user.role==='admin';tableView(admin?'Financeiro':'Meu plano e pagamentos','Registros manuais de cobrança e pagamento. Nenhum gateway conectado.',{headers:['Aluno','Valor','Vencimento','Status','Pagamento','Ações'],rows:state.payments,search:p=>studentName(p.student_id)+' '+p.status,filters:['Pago','Pendente','Vencido','Cancelado'],filter:p=>p.status,export:admin,render:p=>`<tr><td>${person(studentName(p.student_id))}</td><td style="color:var(--text)">${currency(p.amount)}</td><td>${date(p.due)}</td><td>${badge(p.status)}</td><td>${p.paid_at?date(p.paid_at):'—'}</td><td>${admin&&['Pendente','Vencido'].includes(p.status)?btn('Registrar','pay','','small',p.id)+ibtn('Cancelar cobrança','cancel-payment','close',p.id):ibtn('Ver registro','payment-detail','eye',p.id)}</td></tr>`},admin?`<div class="row">${btn('Vincular plano','subscribe','card')}${btn('Gerar cobrança','new-payment','plus','primary')}</div>`:'');if(!admin){const s=state.students[0];$('#content').insertAdjacentHTML('afterbegin',`<div class="banner">${icon('card')}<div>Seu plano: <strong class="violet">${esc(s?.plan||'Nenhum plano contratado')}</strong><br>Consulte sua academia para alterar a assinatura ou efetuar pagamentos.</div></div>`)}}
function workoutHistory(){tableView('Histórico de treinos','Seu esforço registrado, exercício por exercício.',{headers:['Data','Treino','Exercícios','Ações'],rows:state.sessions,search:s=>s.created,render:s=>`<tr><td>${date(s.created)}</td><td>${esc(state.workouts.find(w=>w.id===s.workout_id)?.name||'Treino')}</td><td>${s.logs.length}</td><td>${ibtn('Ver execução','session-detail','eye',s.id)}</td></tr>`})}
function studentDetail(id){const s=state.students.find(s=>s.id===id);if(!s){$('#content').innerHTML=empty('Aluno não encontrado');return}const ws=state.workouts.filter(w=>w.student_id===id),as=state.assessments.filter(a=>a.student_id===id),ats=state.attendance.filter(a=>a.student_id===id),ps=state.payments.filter(p=>p.student_id===id);$('#content').innerHTML=`<button class="text-link" data-route="students">← Voltar para alunos</button><div class="panel detail-hero">${avatar(s.name)}<div><h1>${esc(s.name)}</h1><p class="muted">${esc(s.email)} · ${esc(s.phone)}</p></div><span style="margin-left:auto">${badge(s.active?'Ativo':'Inativo')}</span></div><div class="tabs">${[['overview','Visão geral'],['workouts','Treinos'],['assessments','Avaliações'],['attendance','Frequência'],...(state.user.role==='admin'?[['payments','Financeiro']]:[])].map(([key,label])=>`<button data-action="detail-tab" data-id="${key}" class="${detailTab===key?'active':''}">${label}</button>`).join('')}</div>`;
let body='';if(detailTab==='overview')body=panel('Informações do aluno','Cadastro e acompanhamento',`<div class="details-grid">${[['Professor',s.teacher],['Plano',s.plan||'Sem plano'],['Matrícula',date(s.enrollment)],['Nascimento',date(s.birthday)],['Objetivo',s.objective||'Não informado'],['Dados de avaliação',s.consent?'Autorização registrada':'Sem autorização']].map(([k,v])=>`<div><small>${k}</small>${esc(v)}</div>`).join('')}</div><div class="row" style="margin-top:24px;flex-wrap:wrap">${state.user.role==='admin'?btn('Editar cadastro','edit-student','edit','',s.id)+btn('Vincular plano','subscribe-student','card','',s.id)+(s.active?btn('Desativar aluno','deactivate-student','trash','danger',s.id):''):''}${btn('Registrar check-in','checkin-student','calendar','',s.id)}</div>`);
if(detailTab==='workouts')body=panel('Fichas de treino','Histórico preservado em cada atualização',ws.map(w=>`<div class="between activity-item"><div><strong>${esc(w.name)}</strong><p class="muted">Ficha ${esc(w.division)} · ${w.exercises.length} exercícios</p></div>${btn('Abrir','view-workout','eye','small',w.id)}</div>`).join('')||empty());
if(detailTab==='assessments')body=panel('Histórico de avaliações','Informações de acesso restrito',as.length?lineChart([...as].reverse().map(a=>({label:date(a.date).slice(0,5),value:a.weight})))+as.map(a=>`<div class="between activity-item"><div><strong>${date(a.date)}</strong><p class="muted">${a.weight} kg · ${a.height} cm</p></div>${btn('Ver avaliação','view-assessment','chart','small',a.id)}</div>`).join(''):empty());
if(detailTab==='attendance')body=panel('Presenças',`${ats.length} check-ins registrados`,ats.map(a=>`<div class="between activity-item"><span>${date(a.day)}</span><span class="muted">${a.time}</span>${badge('Confirmado')}</div>`).join('')||empty());
if(detailTab==='payments')body=panel('Histórico financeiro','Cobranças e registros manuais',ps.map(p=>`<div class="between activity-item"><span>${date(p.due)}</span><strong>${currency(p.amount)}</strong>${badge(p.status)}${['Pendente','Vencido'].includes(p.status)?btn('Registrar','pay','','small',p.id):''}</div>`).join('')||empty());$('#content').insertAdjacentHTML('beforeend',body)}
function reports(){const s=sums(),data=series('enrollment');$('#content').innerHTML=heading('Relatórios','Informação clara para decisões com mais contexto.',btn('Exportar financeiro','export-financial','download'))+`<div class="stats">${stat('Receita do mês',currency(s.revenue),'wallet','Calculada pelos pagamentos registrados')}${stat('Alunos ativos',s.active,'users',`${state.students.length-s.active} inativos`)}${stat('Professores ativos',state.teachers.filter(t=>t.active).length,'teacher','Equipe de acompanhamento')}${stat('Inadimplência',currency(s.pending.filter(p=>p.status==='Vencido').reduce((s,p)=>s+p.amount,0)),'alert','Cobranças com vencimento anterior a hoje')}</div><div class="dashboard-grid">${panel('Evolução de matrículas','Novos alunos por mês',lineChart(data))}${panel('Distribuição de planos','Assinaturas ativas',state.plans.map(p=>{const count=state.subscriptions.filter(s=>s.active&&s.plan_id===p.id).length,total=state.subscriptions.filter(s=>s.active).length;return `<div style="margin-bottom:20px"><div class="between"><span>${esc(p.name)}</span><span class="muted">${count} alunos</span></div><div class="progress-track"><span style="width:${count/Math.max(1,total)*100}%"></span></div></div>`}).join(''))}</div>`+panel('Atividade administrativa','Últimas 100 operações auditadas',state.audit.map(a=>`<div class="between activity-item"><div><strong>${esc(a.action)}</strong><p class="muted">${esc(a.actor)} · ${esc(a.entity)} #${a.entity_id||'—'}</p></div><small class="dim">${date(a.created)}</small></div>`).join('')||empty('Nenhuma operação registrada','Novas operações serão auditadas automaticamente.'))}
function settings(){$('#content').innerHTML=heading('Configurações','Identidade da academia e serviços conectados.')+`<div class="dashboard-grid">${panel('Sua academia','Informações usadas no ambiente',`<form id="settings-form" class="form-grid">${field('Nome da academia','gym_name',state.settings.gym_name)}${field('Telefone','phone',state.settings.phone,'tel',false)}${field('Endereço','address',state.settings.address,'text',false,'full')}<div class="field full"><button class="button primary" type="submit">Salvar alterações</button></div></form>`)}${panel('Integrações','Status real dos serviços',`<div class="alert-item"><span class="alert-icon purple">${icon('spark')}</span><div><strong>Assistente de IA</strong><p>Indisponível. Não há modelo de IA conectado.</p></div></div><div class="alert-item"><span class="alert-icon purple">${icon('mail')}</span><div><strong>E-mail e recuperação de senha</strong><p>Indisponível. Requer serviço de envio e fluxo seguro de recuperação.</p></div></div><div class="alert-item"><span class="alert-icon purple">${icon('wallet')}</span><div><strong>Gateway de pagamento</strong><p>Não conectado. Os pagamentos são registros manuais.</p></div></div>`)}</div>`;$('#settings-form').onsubmit=async e=>{e.preventDefault();await saveAction(e.currentTarget,'settings','PUT',formObject(e.currentTarget),false)}}
function profile(){$('#content').innerHTML=heading('Meu perfil','Seus dados, suas preferências.')+panel('Informações pessoais',`${roleName()} · ${esc(state.user.email)}`,`<form id="profile-form" class="form-grid">${field('Nome completo','name',state.user.name)}${field('Telefone','phone',state.user.phone,'tel',false)}<div class="form-section">Alterar senha (opcional)</div>${field('Senha atual','current_password','','password',false)}${field('Nova senha · mínimo de 12 caracteres','new_password','','password',false)}<div class="field full"><button type="submit" class="button primary">Salvar perfil</button></div></form>`);$('#profile-form').onsubmit=async e=>{e.preventDefault();await saveAction(e.currentTarget,'profile','PUT',formObject(e.currentTarget),false)}}
let fieldUID=0;
function field(label,name,value='',type='text',required=true,classes=''){const fieldId=['sets','reps','load','rest'].includes(name)?`f-${name}-${++fieldUID}`:`f-${name}`;return `<div class="field ${classes}"><label for="${fieldId}">${label}${required?' <span class="violet">*</span>':''}</label><input id="${fieldId}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'step="any" min="0"':''} ${type==='password'?'autocomplete="new-password"':''} maxlength="5000"></div>`}
function selectField(label,name,items,value='',required=true,classes=''){return `<div class="field ${classes}"><label for="f-${name}">${label}${required?' <span class="violet">*</span>':''}</label><select name="${name}" id="f-${name}" ${required?'required':''}>${required?'<option value="">Selecione…</option>':''}${items.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`}
function textarea(label,name,value='',required=true){return `<div class="field full"><label for="f-${name}">${label}</label><textarea name="${name}" id="f-${name}" ${required?'required':''} maxlength="5000">${esc(value)}</textarea></div>`}
function studentSelect(value='',locked=false){const items=state.students.filter(s=>s.active||s.id===value).map(s=>[s.id,s.name]);return selectField('Aluno','student_id',items,value)}
function formObject(form){return Object.fromEntries(new FormData(form))}
function modal(title,subtitle,body,onSubmit=null,wide=false,submit='Salvar'){lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div>${ibtn('Fechar janela','close-modal','close')}</header><form id="modal-form"><div class="modal-content">${body}<div class="error-message" id="modal-error" role="alert"></div></div><footer class="modal-footer">${btn(onSubmit?'Cancelar':'Fechar','close-modal','','ghost')}${onSubmit?`<button type="submit" class="button primary">${submit}</button>`:''}</footer></form></section></div>`;document.body.style.overflow='hidden';const f=$('#modal-form');f.onsubmit=async e=>{e.preventDefault();$('#modal-error').textContent='';if(onSubmit)try{await onSubmit(f)}catch(err){$('#modal-error').textContent=err.message}};setTimeout(()=>$('#overlay input, #overlay select, #overlay textarea, #overlay button')?.focus(),30)}
function closeModal(){stopRestTimer();restDeadline=0;restRemaining=0;if(runWorkout&&$('#run-rows'))captureRunDraft();$('#overlay').innerHTML='';document.body.style.overflow='';runWorkout=null;lastFocus?.focus()}
async function saveAction(form,path,method,data,close=true){const submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;try{await api(path,method,data);await refresh();if(close)closeModal();render();toast('Alterações salvas com sucesso.')}catch(e){if(!close)toast(e.message,true);else throw e}finally{if(submit)submit.disabled=false}}
function editUser(kind,id){const teacher=kind==='teacher',record=(teacher?state.teachers:state.students).find(x=>x.id===Number(id)),r=record||{};modal(`${record?'Editar':'Novo'} ${teacher?'professor':'aluno'}`,record?'Atualize o cadastro. O histórico será preservado.':'O acesso será criado com o perfil correto no servidor.',`<div class="form-grid"><div class="form-section">Dados pessoais</div>${field('Nome completo','name',r.name)}${field('E-mail de acesso','email',r.email,'email')}${field('Telefone','phone',r.phone,'tel',false)}${!record?field('Senha inicial · mínimo de 12 caracteres','password','','password'):selectField('Situação','active',[[1,'Ativo'],[0,'Inativo']],r.active)}${teacher?`${field('Especialidade','specialty',r.specialty)}${field('Registro profissional','registration',r.registration,'text',false)}`:`${field('Data de nascimento','birthday',r.birthday,'date',false)}${selectField('Professor responsável','teacher_id',state.teachers.filter(t=>t.active).map(t=>[t.id,t.name]),r.teacher_id)}${textarea('Objetivo do aluno','objective',r.objective,false)}<div class="field full"><label class="checkbox-label"><input type="checkbox" name="consent" ${r.consent?'checked':''}><span>Autorização para dados de avaliação registrada pelo aluno. Confirme que a autorização foi obtida antes de marcar.</span></label></div>`}</div>`,async form=>{const data=formObject(form);data.consent=form.elements.consent?.checked?1:0;await saveAction(form,(teacher?'teachers':'students')+(record?'/'+id:''),record?'PUT':'POST',data)})}
function editPlan(id){const r=state.plans.find(p=>p.id===Number(id))||{};modal(`${r.id?'Editar':'Novo'} plano`,'Defina valor, periodicidade e benefícios.',`<div class="form-grid">${field('Nome do plano','name',r.name)}${field('Valor por período (R$)','price',r.price,'number')}${field('Periodicidade (meses)','months',r.months||1,'number')}${r.id?selectField('Situação','active',[[1,'Ativo'],[0,'Inativo']],r.active):''}${textarea('Descrição','description',r.description)}${textarea('Benefícios · separe por •','benefits',r.benefits)}</div>`,form=>saveAction(form,'plans'+(r.id?'/'+r.id:''),r.id?'PUT':'POST',formObject(form)))}
function editExercise(id){const r=state.exercises.find(e=>e.id===Number(id))||{};modal(`${r.id?'Editar':'Novo'} exercício`,'Oriente a execução com clareza e segurança.',`<div class="form-grid">${field('Nome','name',r.name)}${field('Grupo muscular','muscle',r.muscle)}${field('Equipamento','equipment',r.equipment)}${selectField('Nível','level',[['Iniciante','Iniciante'],['Intermediário','Intermediário'],['Avançado','Avançado']],r.level||'Iniciante')}${textarea('Instruções de execução','instructions',r.instructions)}${textarea('Cuidados gerais','precautions',r.precautions,false)}${r.id?selectField('Situação','active',[[1,'Ativo'],[0,'Inativo']],r.active):''}</div>`,form=>saveAction(form,'exercises'+(r.id?'/'+r.id:''),r.id?'PUT':'POST',formObject(form)))}
function subscribe(sid=''){modal('Vincular plano','A assinatura anterior será encerrada e uma nova cobrança será gerada.',`<div class="form-grid">${studentSelect(sid)}${selectField('Plano','plan_id',state.plans.filter(p=>p.active).map(p=>[p.id,`${p.name} · ${currency(p.price)} / ${p.months} mês(es)`]))}${field('Vencimento da primeira cobrança','due',state.today,'date')}<div class="field full banner">${icon('card')}O valor da cobrança será calculado no servidor a partir do plano selecionado.</div></div>`,form=>saveAction(form,'subscriptions','POST',formObject(form)),false,'Vincular e gerar cobrança')}
function checkin(sid){if(sid){return confirmAction('Confirmar check-in',`Registrar a presença de ${studentName(Number(sid))} hoje?`,'attendance','POST',{student_id:Number(sid)},'Registrar presença')}modal('Registrar check-in','A data e o horário serão definidos pelo servidor.',`<div class="form-grid">${studentSelect()}<div class="field full banner">${icon('shield')}É permitido um check-in por aluno por dia. Duplicações são bloqueadas no banco de dados.</div></div>`,form=>saveAction(form,'attendance','POST',formObject(form)),false,'Registrar presença')}
function editAssessment(id){const r=state.assessments.find(a=>a.id===Number(id))||{};modal(`${r.id?'Editar':'Nova'} avaliação`,'Dados restritos ao aluno e aos profissionais autorizados.',`<div class="form-grid">${studentSelect(r.student_id)}${field('Data da avaliação','date',r.date||state.today,'date')}${field('Peso (kg)','weight',r.weight,'number')}${field('Altura (cm)','height',r.height,'number')}${field('Cintura (cm)','waist',r.waist,'number')}${field('Próxima avaliação','next_date',r.next_date||state.today,'date')}${textarea('Objetivos definidos com o aluno','objective',r.objective)}${textarea('Observações profissionais','notes',r.notes)}<div class="field full"><p class="muted" style="font-size:11px">A autorização para registrar dados de avaliação deve constar no cadastro do aluno. Os indicadores não produzem julgamentos automáticos.</p></div></div>`,form=>saveAction(form,'assessments'+(r.id?'/'+r.id:''),r.id?'PUT':'POST',formObject(form)))}
function captureExercises(){if(!$('#builder-rows'))return;exerciseDraft=$$('#builder-rows .exercise-builder').map(row=>({exercise_id:Number(row.dataset.exid),sets:row.querySelector('[name="sets"]').value,reps:row.querySelector('[name="reps"]').value,load:row.querySelector('[name="load"]').value,rest:row.querySelector('[name="rest"]').value}))}
function builderRows(){$('#builder-rows').innerHTML=exerciseDraft.length?exerciseDraft.map((e,i)=>`<div class="exercise-builder" data-exid="${e.exercise_id}"><div class="between"><strong style="font-size:12px"><span class="violet">${String(i+1).padStart(2,'0')}.</span> ${esc(state.exercises.find(x=>x.id===e.exercise_id)?.name||'Exercício')}</strong><button type="button" class="icon-button" data-action="remove-exercise" data-id="${i}" aria-label="Remover exercício">${icon('close')}</button></div><div class="form-grid">${field('Séries','sets',e.sets,'number')}${field('Repetições','reps',e.reps)}${field('Carga (kg)','load',e.load,'number')}${field('Descanso (seg.)','rest',e.rest,'number')}</div></div>`).join(''):empty('Selecione o primeiro exercício','Configure séries, repetições e descanso para cada movimento.')}
function editWorkout(id){const r=state.workouts.find(w=>w.id===Number(id))||{};exerciseDraft=(r.exercises||[]).map(e=>({...e}));modal(`${r.id?'Editar ficha':'Criar ficha de treino'}`,'1. Defina o objetivo → 2. Configure os exercícios → 3. Salve a ficha',`<div class="form-grid"><div class="form-section">01 · Aluno e objetivo</div>${studentSelect(r.student_id)}${field('Nome do treino','name',r.name)}${selectField('Divisão','division','ABCDEFG'.split('').map(v=>[v,'Ficha '+v]),r.division||'A')}${r.id?selectField('Situação','active',[[1,'Ativo'],[0,'Inativo']],r.active):''}${textarea('Objetivo','objective',r.objective)}${textarea('Orientações','notes',r.notes,false)}<div class="form-section">02 · Exercícios da ficha</div><div class="field full"><div class="row"><select id="exercise-picker" aria-label="Selecionar exercício" style="flex:1"><option value="">Selecione um exercício…</option>${state.exercises.filter(e=>e.active).map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.muscle)}</option>`).join('')}</select><button type="button" class="button" data-action="add-exercise">${icon('plus')}Adicionar</button></div><div id="builder-rows"></div></div></div>`,async form=>{captureExercises();const data=formObject(form);data.exercises=exerciseDraft;if(!data.exercises.length)throw Error('Adicione ao menos um exercício.');await saveAction(form,'workouts'+(r.id?'/'+r.id:''),r.id?'PUT':'POST',data)},true,'Salvar ficha');builderRows();if(r.id)$('#f-student_id').disabled=true;const f=$('#modal-form');const old=f.onsubmit;f.onsubmit=async e=>{if(r.id)$('#f-student_id').disabled=false;await old(e);if(r.id&&$('#f-student_id'))$('#f-student_id').disabled=true}}
function confirmAction(title,message,path,method,data={},label='Confirmar'){modal(title,'Revise antes de continuar.',`<p class="muted">${esc(message)}</p>`,form=>saveAction(form,path,method,data),false,label)}
function viewWorkout(id){const w=state.workouts.find(w=>w.id===Number(id));if(!w)return;modal(esc(w.name),`Ficha ${esc(w.division)} · ${esc(studentName(w.student_id))}`,`<div class="banner">${icon('target')}<div><strong>${esc(w.objective)}</strong><p>${esc(w.notes)}</p></div></div>${w.exercises.map((e,i)=>`<div class="activity-item"><div class="workout-letter">${i+1}</div><div><h3>${esc(e.name)}</h3><p class="muted">${e.sets} × ${esc(e.reps)} · ${e.load} kg · ${e.rest}s de descanso</p><p class="dim" style="font-size:11px;margin-top:6px">${esc(e.instructions)}</p></div></div>`).join('')}${w.versions.length?`<details style="margin-top:20px"><summary class="muted">${w.versions.length} versões anteriores preservadas</summary>${w.versions.map(v=>{const old=JSON.parse(v.snapshot);return `<div class="read-box" style="margin-top:10px"><strong>${esc(old.name)} · ${date(v.created)}</strong><br>${(old.exercises||[]).map(e=>`${esc(e.name)}: ${e.sets} × ${esc(e.reps)}, ${e.load} kg`).join('<br>')}</div>`}).join('')}</details>`:''}${state.user.role==='student'&&w.active?`<div style="margin-top:22px">${btn('Iniciar treino','start-workout','play','primary',w.id)}</div>`:''}`,null,true)}
function captureRunDraft(){if(!runWorkout)return;const draft=$$('#run-rows .exercise-run').map(row=>({exercise_id:Number(row.dataset.exid),load:row.querySelector('[name="load"]').value,reps:row.querySelector('[name="reps"]').value,checked:row.querySelector('[type="checkbox"]').checked}));sessionStorage.setItem(draftKey,JSON.stringify(draft))}
function startWorkout(id){stopRestTimer();restDeadline=0;restRemaining=0;const w=state.workouts.find(w=>w.id===Number(id));if(!w)return;draftKey=`gymflow-run-${state.user.id}-${w.id}-${w.updated}`;let draft=[];try{draft=JSON.parse(sessionStorage.getItem(draftKey)||'[]')}catch{}modal(esc(w.name),'Registre carga e repetições e marque cada exercício realizado.',`<div class="between"><span class="badge">Ficha ${esc(w.division)}</span><span class="muted" id="run-count">0 de ${w.exercises.length}</span></div><div class="progress-track"><span id="run-progress" style="width:0"></span></div><section id="rest-panel" class="rest-panel" hidden aria-label="Cronômetro de descanso"><div><p id="rest-status" role="status"></p><strong id="rest-time" class="number" role="timer">00:00</strong></div><div class="row"><button type="button" id="rest-pause" class="button small" data-action="rest-pause">Pausar</button><button type="button" class="button small ghost" data-action="rest-dismiss">Encerrar</button></div></section>${draft.length?'<p class="draft-notice">Rascunho retomado: seus registros desta aba foram recuperados.</p>':''}<div id="run-rows">${w.exercises.map((e,i)=>{const d=draft[i]?.exercise_id===e.exercise_id?draft[i]:{};return `<div class="exercise-run" data-exid="${e.exercise_id}"><div class="row"><span class="workout-letter violet">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(e.name)}</h3><small class="dim">${e.sets} séries · ${esc(e.reps)} repetições sugeridas · ${e.rest}s de descanso</small></div></div><p>${esc(e.instructions)}</p>${Number(e.rest)>0?`<button type="button" class="button small rest-start" data-action="rest-start" data-id="${e.exercise_id}">${icon('clock')}Descansar ${e.rest}s</button>`:''}<div class="form-grid">${field('Carga realizada (kg)','load',d.load??e.load,'number')}${field('Repetições por série','reps',d.reps??(parseInt(e.reps)||12),'number')}<label class="checkbox-label check"><input type="checkbox" ${d.checked?'checked':''}><span>Realizado</span></label></div></div>`}).join('')}</div><p class="dim" style="font-size:10px;margin-top:18px">O rascunho é mantido nesta aba. Ao concluir, o registro é salvo no banco.</p>`,async form=>{const rows=$$('#run-rows .exercise-run');if(rows.some(r=>!r.querySelector('[type="checkbox"]').checked))throw Error('Marque todos os exercícios realizados antes de concluir.');const logs=rows.map(row=>({exercise_id:Number(row.dataset.exid),load:row.querySelector('[name="load"]').value,reps:row.querySelector('[name="reps"]').value}));const key=draftKey;await saveAction(form,'workout-sessions','POST',{workout_id:w.id,logs});sessionStorage.removeItem(key)},false,'Concluir treino');runWorkout=w;const update=()=>{captureRunDraft();const count=$$('#run-rows input[type="checkbox"]:checked').length;$('#run-count').textContent=`${count} de ${w.exercises.length}`;$('#run-progress').style.width=`${w.exercises.length?count/w.exercises.length*100:0}%`;$$('#run-rows .exercise-run').forEach(row=>row.classList.toggle('completed',row.querySelector('[type="checkbox"]').checked))};$('#run-rows').addEventListener('input',update);update()}
function viewAssessment(id){const a=state.assessments.find(a=>a.id===Number(id));if(!a)return;const records=state.assessments.filter(x=>x.student_id===a.student_id).sort((a,b)=>a.date.localeCompare(b.date));modal('Avaliação e evolução',`${esc(studentName(a.student_id))} · ${date(a.date)}`,`<div class="details-grid">${[['Peso',a.weight+' kg'],['Altura',a.height+' cm'],['Cintura',a.waist+' cm'],['Próxima avaliação',date(a.next_date)]].map(([k,v])=>`<div><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><h3 style="margin:25px 0 12px">Histórico de peso (kg)</h3>${lineChart(records.map(r=>({label:date(r.date).slice(0,5),value:r.weight})))}<h3 style="margin:20px 0 10px">Objetivo</h3><p class="read-box">${esc(a.objective)}</p><h3 style="margin:20px 0 10px">Observações profissionais</h3><p class="read-box">${esc(a.notes)}</p>`,null,true)}
function downloadCSV(data,headers,filename){const csv='\uFEFF'+[headers,...data].map(row=>row.map(v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}).join(';')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportFinancial(){downloadCSV(state.payments.map(p=>[studentName(p.student_id),p.amount,p.due,p.status,p.paid_at||'',p.method]),['Aluno','Valor','Vencimento','Status','Pago em','Método'],'gymflow-financeiro.csv')}
function renderLogin(){$('#app').innerHTML=`<main class="login-page"><section class="login-art"><a class="brand" href="/" aria-label="GymFlow"><span class="brand-symbol">${icon('dumbbell')}</span><span>gym<em>flow</em>.</span></a><span class="label" style="margin-top:70px;color:#bca9ee">ATHLETIC TECH · GESTÃO INTELIGENTE</span><h1>Seu negócio.<br>Seu movimento.<br><span>Seu próximo nível.</span></h1><p>Conecte pessoas, treinos e resultados. Tudo o que a sua academia precisa, em um só lugar.</p><div class="athletic-art" aria-hidden="true"><span></span><span></span><span></span><span></span></div><div class="row muted" style="margin-top:auto;font-size:10px">${icon('shield')}Um espaço para cada perfil. Uma gestão conectada.</div></section><section class="login-form-wrap"><div class="login-form"><div class="stat-icon" style="width:40px;height:40px;margin-bottom:22px">${icon('dumbbell')}</div><h2>Bem-vindo ao GymFlow.</h2><p>Entre na sua conta e continue em movimento.</p><form id="login-form">${field('E-mail','email','','email')}${field('Senha','password','','password')}<button type="button" class="text-link" data-action="recover">Esqueci minha senha</button><div id="login-error" class="error-message" role="alert"></div><button class="button primary" type="submit">Entrar na minha conta ${icon('arrow')}</button></form>${demoEnabled?`<div class="demo-box"><strong style="font-size:11px">Explore o GymFlow</strong><p>Ambiente local de demonstração com dados fictícios. Escolha um perfil para preencher as credenciais e entrar.</p><div class="demo-roles">${btn('Administrador','demo-admin')}${btn('Professor','demo-teacher')}${btn('Aluno','demo-student')}</div><p>Senha demonstrativa: <span class="violet">GymFlow@2026!</span></p></div>`:''}<p style="text-align:center;font-size:10px;color:var(--dim);margin-top:25px">GymFlow · Gestão em movimento.</p></div></section></main>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;const b=f.querySelector('[type="submit"]');b.disabled=true;$('#login-error').textContent='';try{await api('login','POST',formObject(f));await refresh();route='dashboard';render()}catch(err){$('#login-error').textContent=err.message}finally{b.disabled=false}}}
document.addEventListener('click',async event=>{const routeEl=event.target.closest('[data-route]');if(routeEl){event.preventDefault();navigate(routeEl.dataset.route);return}const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;try{switch(a){
case 'close-modal':closeModal();break;
case 'collapse':collapsed=!collapsed;render();break;
case 'mobile-menu':$('.shell').classList.toggle('mobile-open');break;
case 'logout':await api('logout','POST',{});state=null;sessionStorage.clear();closeModal();renderLogin();break;
case 'demo-admin':case 'demo-teacher':case 'demo-student':$('#login-form [name="email"]').value={ 'demo-admin':'admin@gymflow.demo','demo-teacher':'professor1@gymflow.demo','demo-student':'aluno1@gymflow.demo'}[a];$('#login-form [name="password"]').value='GymFlow@2026!';$('#login-form').requestSubmit();break;
case 'recover':modal('Recuperação de senha','Serviço de e-mail não configurado.',`<div class="banner">${icon('mail')}A recuperação automática está indisponível. Este ambiente não possui serviço de e-mail conectado.</div><p class="muted">Na demonstração, utilize os botões de perfil e a senha informada na tela de acesso. Para operação real, configure um serviço de autenticação com recuperação segura.</p>`);break;
case 'help':modal('Um espaço para cada tarefa','GymFlow · Gestão em movimento',`<div class="read-box">Alunos: cadastre, atribua um professor e vincule um plano.\nTreinos: crie fichas com exercícios, séries, cargas e intervalos.\nAvaliações: registre a autorização do aluno e acompanhe sua evolução.\nFrequência: registre um check-in por dia.\nFinanceiro: vincule planos, gere cobranças e registre pagamentos manuais.\n\nOs dados desta demonstração são fictícios. IA, envio de e-mail e gateway de pagamentos não estão conectados.</div>`);break;
case 'notifications':{const exp=state.payments.filter(p=>p.status==='Vencido');modal('Notificações','Alertas calculados com os registros do banco.',state.notifications.map(n=>`<div class="activity-item"><div>${esc(n.title)}<p class="dim">${date(n.created)}</p></div></div>`).join('')+(exp.length?`<div class="banner" style="margin-top:15px">${icon('alert')}${exp.length} cobranças vencidas · ${currency(exp.reduce((s,p)=>s+p.amount,0))}</div>`:'')||empty('Tudo em dia'));break}
case 'period':period=Number(id);dashboard();break;
case 'prev-page':tablePage=Math.max(1,tablePage-1);updateTable();break;
case 'next-page':tablePage++;updateTable();break;
case 'new-student':editUser('student');break;
case 'edit-student':editUser('student',id);break;
case 'new-teacher':editUser('teacher');break;
case 'edit-teacher':editUser('teacher',id);break;
case 'deactivate-student':confirmAction('Desativar aluno','O acesso será bloqueado e o histórico permanecerá preservado.','students/'+id,'DELETE');break;
case 'deactivate-teacher':confirmAction('Desativar professor','O acesso será bloqueado. Os vínculos e históricos serão preservados; reatribua os alunos se necessário.','teachers/'+id,'DELETE');break;
case 'student-detail':navigate('students/'+id);break;
case 'detail-tab':detailTab=id;studentDetail(Number(route.split('/')[1]));break;
case 'new-plan':editPlan();break;
case 'edit-plan':editPlan(id);break;
case 'deactivate-plan':confirmAction('Desativar plano','O plano deixará de estar disponível para novas assinaturas. Contratos e cobranças existentes serão preservados.','plans/'+id,'DELETE');break;
case 'new-exercise':editExercise();break;
case 'edit-exercise':editExercise(id);break;
case 'view-exercise':{const e=state.exercises.find(e=>e.id===Number(id));modal(esc(e.name),`${esc(e.muscle)} · ${esc(e.equipment)} · ${esc(e.level)}`,`<h3 style="margin-bottom:12px">Como executar</h3><p class="read-box">${esc(e.instructions)}</p><h3 style="margin:20px 0 12px">Cuidados gerais</h3><p class="read-box">${esc(e.precautions||'Consulte seu professor para orientação.')}</p>${state.user.role!=='student'&&e.active?`<div style="margin-top:20px">${btn('Desativar exercício','deactivate-exercise','trash','danger',e.id)}</div>`:''}`);break}
case 'deactivate-exercise':confirmAction('Desativar exercício','O exercício será removido das opções para novas fichas. As fichas e os registros existentes serão preservados.','exercises/'+id,'DELETE');break;
case 'subscribe':subscribe();break;
case 'subscribe-student':subscribe(Number(id));break;
case 'new-attendance':checkin();break;
case 'checkin-student':checkin(id);break;
case 'self-checkin':checkin(state.user.id);break;
case 'new-assessment':editAssessment();break;
case 'edit-assessment':editAssessment(id);break;
case 'view-assessment':viewAssessment(id);break;
case 'new-workout':editWorkout();break;
case 'edit-workout':editWorkout(id);break;
case 'view-workout':viewWorkout(id);break;
case 'add-exercise':{const eid=Number($('#exercise-picker').value);if(!eid){toast('Selecione um exercício.',true);break}captureExercises();exerciseDraft.push({exercise_id:eid,sets:3,reps:'12',load:0,rest:60});builderRows();$('#exercise-picker').value='';break}
case 'remove-exercise':captureExercises();exerciseDraft.splice(Number(id),1);builderRows();break;
case 'rest-start':{const exercise=runWorkout?.exercises.find(e=>e.exercise_id===Number(id));if(exercise)startRestTimer(exercise.rest,exercise.name);break}
case 'rest-pause':toggleRestTimer();break;
case 'rest-dismiss':stopRestTimer();restDeadline=0;restRemaining=0;$('#rest-panel').hidden=true;break;
case 'start-workout':startWorkout(id);break;
case 'new-payment':modal('Gerar cobrança','O valor será calculado a partir do plano ativo do aluno.',`<div class="form-grid">${studentSelect()}${field('Vencimento','due',state.today,'date')}</div>`,form=>saveAction(form,'payments','POST',formObject(form)),false,'Gerar cobrança');break;
case 'pay':{const p=state.payments.find(p=>p.id===Number(id));modal('Registrar pagamento manual',`${esc(studentName(p.student_id))} · ${currency(p.amount)}`,`<div class="banner">${icon('wallet')}Este registro não confirma uma transação bancária. Confira o recebimento antes de continuar.</div><div class="form-grid">${selectField('Forma de recebimento','method',[['Pix conferido manualmente','Pix conferido manualmente'],['Dinheiro','Dinheiro'],['Cartão conferido manualmente','Cartão conferido manualmente'],['Transferência conferida manualmente','Transferência conferida manualmente']])}</div>`,form=>saveAction(form,'payments/'+id,'PUT',{...formObject(form),status:'Pago'}),false,'Confirmar registro');break}
case 'cancel-payment':confirmAction('Cancelar cobrança','A cobrança será preservada no histórico com o status Cancelado.','payments/'+id,'PUT',{status:'Cancelado'});break;
case 'payment-detail':{const p=state.payments.find(p=>p.id===Number(id));modal('Detalhes da cobrança',esc(studentName(p.student_id)),`<div class="read-box">Valor: ${currency(p.amount)}\nVencimento: ${date(p.due)}\nStatus: ${esc(p.status)}\nPagamento: ${date(p.paid_at)}\nMétodo: ${esc(p.method||'Não registrado')}\n\nRegistro manual. Não representa confirmação de um gateway.</div>`);break}
case 'session-detail':{const s=state.sessions.find(s=>s.id===Number(id));modal('Treino concluído',date(s.created),s.logs.map(l=>`<div class="activity-item"><div><h3>${esc(l.name)}</h3><p class="muted">${l.sets} séries × ${l.reps} repetições · ${l.load} kg</p></div></div>`).join(''));break}
case 'go-payments':navigate('payments');break;
case 'go-reports':navigate('reports');break;
case 'go-exercises':navigate('exercises');break;
case 'go-profile':navigate('profile');break;
case 'export-financial':exportFinancial();break;
case 'export':{const base=route.split('/')[0],all=filteredRows();if(base==='payments'){downloadCSV(all.map(p=>[studentName(p.student_id),p.amount,p.due,p.status]),['Aluno','Valor','Vencimento','Status'],'gymflow-cobrancas.csv')}else if(base==='attendance'){downloadCSV(all.map(a=>[studentName(a.student_id),a.day,a.time]),['Aluno','Data','Hora'],'gymflow-frequencia.csv')}else downloadCSV(all.map(s=>[s.name,s.email,s.phone,s.plan,s.teacher,s.active?'Ativo':'Inativo']),['Nome','E-mail','Telefone','Plano','Professor','Status'],'gymflow-alunos.csv');break}
}}catch(err){toast(err.message,true)}});
document.addEventListener('keydown',event=>{const modalEl=$('#overlay .modal');if(!modalEl)return;if(event.key==='Escape'){closeModal();return}if(event.key==='Tab'){const items=[...modalEl.querySelectorAll('button,input,select,textarea,a')].filter(el=>!el.disabled&&el.offsetParent!==null),first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}});
(async()=>{try{const config=await api('config');demoEnabled=config.demo;await refresh();route=location.hash.slice(1)||'dashboard';render()}catch{renderLogin()}})();
